def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if len(alive_opponents) == 0:
        base = DAILY_SALARY * 0.22
        if hp <= 2 or no_water >= 1:
            base = DAILY_SALARY * 0.45
        return float(max(0.0, min(budget, base)))

    prev_bids = []
    desperate_count = 0
    rich_aggressive = 0
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        bid = None
        if prev:
            bid = prev.get('bid')
        if bid is not None:
            prev_bids.append(float(bid))
        if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
            desperate_count += 1
        if opp.get('budget', 0) >= 300:
            if bid is not None and float(bid) >= 90:
                rich_aggressive += 1

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = (sum(prev_bids) / len(prev_bids)) if prev_bids else 0.0

    scarcity = (25.0 - float(supply)) / 10.0
    if scarcity < 0:
        scarcity = 0.0
    if scarcity > 1:
        scarcity = 1.0

    urgent = False
    if hp <= 2 or no_water >= 2:
        urgent = True
    elif hp <= 4 and no_water >= 1:
        urgent = True

    very_safe = False
    if hp >= 8 and no_water == 0:
        very_safe = True

    if urgent:
        target = max(92.0, highest_prev + 2.5)
        if desperate_count >= 2:
            target += 8.0
        if float(supply) <= 17.0:
            target += 6.0
        if day >= 8:
            target += 5.0
    else:
        if very_safe:
            target = 12.0 + 10.0 * (1.0 - scarcity)
            if highest_prev < 40.0:
                target = max(target, highest_prev + 1.0)
            else:
                target = min(target, 24.0)
        else:
            target = 28.0 + 18.0 * scarcity
            if no_water >= 1:
                target += 18.0
            if hp <= 5:
                target += 10.0
            if highest_prev > 0:
                if highest_prev <= 60.0:
                    target = max(target, highest_prev + 1.5)
                elif highest_prev <= 95.0:
                    target = max(target, 0.72 * highest_prev)
                else:
                    target = max(target, 0.58 * highest_prev)

    if rich_aggressive >= 2 and not urgent:
        target *= 0.82
    elif rich_aggressive == 1 and not urgent:
        target *= 0.9

    if avg_prev > 100.0 and not urgent and hp >= 6:
        target = min(target, 36.0)

    reserve_floor = 0.0
    if hp >= 6:
        reserve_floor = DAILY_SALARY * 2.0
    elif hp >= 4:
        reserve_floor = DAILY_SALARY * 1.2
    else:
        reserve_floor = DAILY_SALARY * 0.4

    max_spend = budget
    if not urgent:
        max_spend = max(0.0, budget - reserve_floor)
        if max_spend < 8.0:
            max_spend = min(budget, 8.0)

    if day >= 9 and hp <= 4:
        max_spend = budget
        target += 12.0

    bid = min(max_spend, target)
    if urgent:
        bid = min(budget, max(bid, 88.0 if float(supply) >= 18.0 else 96.0))

    if bid < 0:
        bid = 0.0
    return float(min(budget, bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    my_hp = int(my_status.get('hp', 0))
    my_budget = float(my_status.get('budget', 0.0))
    my_no_water_days = int(my_status.get('no_water_days', 0))

    alive_opponents = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opponents.append((oid, o))

    if not alive_opponents:
        return min(my_budget, DAILY_SALARY * 0.4)

    # Read yesterday bids from each opponent's previous_trace
    yesterday_bids = []
    for _, o in alive_opponents:
        prev = o.get('previous_trace', {}) or {}
        bid = prev.get('bid', None)
        if bid is not None:
            try:
                yesterday_bids.append(float(bid))
            except Exception:
                pass

    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0

    # Base target: moderate bid to avoid getting outcompeted when others are aggressive.
    # If someone yesterday bid very high, assume they will continue; increase ours.
    # If our HP is low, prioritize survival.
    if my_hp <= 2 or my_no_water_days >= 2:
        target = DAILY_SALARY * 0.85
    else:
        if highest_prev_bid >= DAILY_SALARY * 1.15:
            # Arms-race signal (e.g., Cindy-like aggressiveness)
            target = DAILY_SALARY * 0.65
        elif highest_prev_bid >= DAILY_SALARY * 0.75:
            target = DAILY_SALARY * 0.55
        else:
            target = DAILY_SALARY * 0.45

    # Supply-aware adjustment: if supply is tight, bids need to be stronger.
    # Estimate how many full water units are likely available.
    # Use int indices defensively.
    supply_int = int(round(supply))
    units = int(supply_int / int(WATER_REQ)) if WATER_REQ > 0 else 0
    # If units are 0, it's extremely tight; push higher.
    if units <= 0:
        target *= 1.15
    elif units == 1:
        target *= 1.05

    # Ensure we don't exceed budget
    bid = min(my_budget, float(target))

    # Keep bid non-negative
    if bid < 0.0:
        bid = 0.0

    return bid
